async function createEvent({ title, startTime, endTime, timezone, attendees }) {
  const startUtc = DateTime.fromISO(startTime, { zone: timezone }).toUTC();
  const endUtc = DateTime.fromISO(endTime, { zone: timezone }).toUTC();

  const event = await calendarApi.events.insert({
    summary: title,
    start: { dateTime: startUtc.toISO(), timeZone: "UTC" },
    end: { dateTime: endUtc.toISO(), timeZone: "UTC" },
    attendees: attendees.map((email) => ({ email })),
  });

  return { eventId: event.id, startLocal: startUtc.setZone(timezone).toISO() };
}

def ranges_overlap(a_start, a_end, b_start, b_end):
    # all four values must already be in UTC before this check runs
    return a_start < b_end and b_start < a_end

def find_common_slot(attendee_busy_utc, search_start, search_end, duration_minutes):
    all_busy = sorted(sum(attendee_busy_utc.values(), []), key=lambda b: b[0])
    merged = merge_busy_ranges(all_busy)
    candidate = search_start
    for busy_start, busy_end in merged:
        free_minutes = (busy_start - candidate).total_seconds() / 60
        if free_minutes >= duration_minutes:
            return candidate, candidate + timedelta(minutes=duration_minutes)
        candidate = max(candidate, busy_end)
    if (search_end - candidate).total_seconds() / 60 >= duration_minutes:
        return candidate, candidate + timedelta(minutes=duration_minutes)
    return None
